            const kb = getMapLockKeybind();
            if (e.altKey || e.metaKey) return;
            if (kb.ctrl !== e.ctrlKey) return;
            if (kb.shift !== e.shiftKey) return;
            if (e.key.toUpperCase() !== (kb.key || 'L').toUpperCase()) return;
